def fillet_edges(self):
    class EdgeSelector(cq.Selector):
        def __init__(self, thickness, leg_length):
            self.thickness = thickness
            self.leg_length = leg_length
        def filter(self, objectList):
            result = []
            for edge in objectList:
                c = edge.Center()
                if (abs(c.x - self.thickness) < 1e-3 and abs(c.y - self.thickness) < 1e-3) or (abs(c.x - self.leg_length) < 1e-3):
                    result.append(edge)
            return result

    self.model = self.model.edges("|Z").edges(EdgeSelector(self.thickness, self.leg_length)).fillet(self.fillet_radius)
